export default function Icon({
  name,
  size = 20,
  color = "var(--color-background, #ffa552)",
  style,
  className,
}: {
  name: IconName;
  size?: number;
  color?: string;
  style?: CSSProperties;
  className?: string;
}) {
  const px = Math.max(20, size);
  const body = BODIES[name];
  if (!body) return null;
  return (
    <svg
      viewBox="0 0 24 24"
      width={px}
      height={px}
      role="presentation"
      aria-hidden="true"
      className={className}
      style={{ color, display: "block", flex: "0 0 auto", ...style }}
      dangerouslySetInnerHTML={{ __html: body }}
    />
  );
}
